fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Check that x and y have the same positive length
    if x.len() != y.len() || x.is_empty() {
        panic!("Input arrays must have equal positive length.");
    }

    // Check that the coefficient grid is non-empty and every row is non-empty
    if c.is_empty() || c.iter().any(|row| row.is_empty()) {
        panic!("Coefficient grid must be non-empty and every row must be non-empty.");
    }

    // If the coefficient grid is 1x1, fill the output with that single value
    if c.len() == 1 && c[0].len() == 1 {
        let value = default_value(&c);
        return vec![value; x.len()];
    }

    // Otherwise, return an output array filled with zeros
    vec![0.0; x.len()]
}

fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // Since we assume c is 1x1 here, we can safely return the single value
    c[0][0]
}

